    Console.WriteLine($"\nCsc task in: {t.Project?.Name}");
    var commandLine = t.FindChildrenRecursive<Property>().FirstOrDefault(p => p.Name == "CommandLineArguments");
    if (commandLine != null) Console.WriteLine($"  Args snippet: {commandLine.Value?.Substring(0, Math.Min(200, commandLine.Value.Length))}");
}
